import type { OpenChangeReason } from "@floating-ui/react";
import findIndex from "lodash/findIndex";
import type React from "react";
import { useEffect, useRef, useState } from "react";

import { VisuallyHidden } from "../shared/accessibility";
import {
    DropdownList,
    DropdownListState,
    ExpandableElement,
    SelectedTagList,
} from "../shared/dropdown-list";
import { ElementWithDropdown } from "../shared/dropdown-wrapper";
import {
    LabelContainer,
    PlaceholderLabel,
    ValueLabel,
} from "../shared/dropdown-wrapper/dropdown-wrapper";
import { InputBox } from "../shared/input-wrapper/input-wrapper";
import { useId } from "../util";
import type { InputMultiSelectProps } from "./types";

// @catalog
/**
 * A dropdown field that lets users select multiple options from a list.
 *
 * Use `InputMultiSelect` when users need to pick one or more items from a
 * predefined list.
 * @keywords combobox, dropdown, field, form, input, multi-value, multiple, select
 */
export const InputMultiSelect = <T, V>({
    selectedOptions,
    placeholder = "Select",
    options,
    disabled,
    error,
    className,
    "data-testid": testId,
    id,
    "aria-labelledby": ariaLabelledBy,
    "aria-describedby": ariaDescribedBy,
    "aria-invalid": ariaInvalid,
    enableSearch = false,
    searchFunction,
    searchPlaceholder,
    valueExtractor,
    listExtractor,
    onSelectOptions,
    onShowOptions,
    onHideOptions,
    onRetry,
    optionsLoadState = "success",
    optionTruncationType = "end",
    renderListItem,
    hideNoResultsDisplay,
    noResultsDescription,
    customLabels,
    renderCustomCallToAction,
    onBlur,
    variant = "default",
    displayVariant = "count",
    readOnly,
    alignment,
    dropdownZIndex,
    maxSelectable,
    dropdownRootNode,
    dropdownWidth,
}: InputMultiSelectProps<T, V>): JSX.Element => {
    // =============================================================================
    // CONST, STATE
    // =============================================================================
    const { allSelectedLabel, multiSelectedLabel } = customLabels || {};
    const [selected, setSelected] = useState<T[]>(selectedOptions || []);
    const [showOptions, setShowOptions] = useState<boolean>(false);
    const [focused, setFocused] = useState<boolean>(false);
    const internalId = useId();

    const nodeRef = useRef<HTMLDivElement>(null);
    const selectorRef = useRef<HTMLButtonElement>(null);

    // =============================================================================
    // EFFECTS
    // =============================================================================
    useEffect(() => {
        setSelected(selectedOptions || []);
    }, [selectedOptions]);

    // =============================================================================
    // EVENT HANDLERS
    // =============================================================================
    const handleSelectAllClick = () => {
        if ((selected && selected.length > 0) || maxSelectable) {
            setSelected([]);
            performOnSelectOptions([]);
        } else {
            setSelected(options);
            performOnSelectOptions(options);
        }
    };

    const handleListItemClick = (item: T, extractedValue: T | V) => {
        const selectedCopy = [...selected];

        // Check if it is a selection or deselection
        const itemIndex = findIndex(selected, (item) => {
            const valueToCompare = valueExtractor ? valueExtractor(item) : item;
            return valueToCompare === extractedValue;
        });

        if (itemIndex > -1) {
            // Item exists in selected. This indicates a deselection
            selectedCopy.splice(itemIndex, 1);
        } else {
            // Item does not exist in selected. This indicates a selection
            selectedCopy.push(item);
        }

        setSelected(selectedCopy);
        performOnSelectOptions(selectedCopy);
    };

    const handleListDismiss = () => {
        if (showOptions) {
            setShowOptions(false);
            triggerOptionDisplayCallback(false);
        }
    };

    const handleNodeFocus = () => {
        if (!focused && !showOptions) {
            setFocused(true);
        }
    };

    const handleNodeBlur = (e: React.FocusEvent) => {
        if (
            focused &&
            !showOptions &&
            nodeRef.current &&
            !nodeRef.current.contains(e.relatedTarget as Node)
        ) {
            setFocused(false);
            onBlur?.();
        }
    };

    const handleOpen = () => {
        setShowOptions(true);
        triggerOptionDisplayCallback(true);
        setFocused(true);
    };

    const handleClose = (reason: OpenChangeReason | undefined) => {
        setShowOptions(false);
        triggerOptionDisplayCallback(false);

        // click to toggle should not blur the input
        if (reason !== "click") {
            setFocused(false);
            onBlur?.();
        }
    };

    const handleDismiss = () => {
        selectorRef.current?.focus();
        setShowOptions(false);
        triggerOptionDisplayCallback(false);
    };

    // =============================================================================
    // HELPER FUNCTION
    // =============================================================================
    const getTagLabel = (item: T): string => {
        const value = listExtractor ? listExtractor(item) : item?.toString();

        if (typeof value === "object") {
            return value.title;
        }

        return value ?? "";
    };

    const getTagKey = (item: T, index: number) => {
        const formattedValue = valueExtractor ? valueExtractor(item) : item;
        return `item_${index}__${formattedValue}`;
    };

    const getDisplayValue = () => {
        if (options && selected.length === options.length) {
            return allSelectedLabel || "All selected";
        }

        return multiSelectedLabel || `${selected.length} selected`;
    };

    const triggerOptionDisplayCallback = (show: boolean) => {
        if (!show && onHideOptions) {
            onHideOptions();
        }

        if (show && onShowOptions) {
            onShowOptions();
        }
    };

    const performOnSelectOptions = (options: T[]) => {
        if (onSelectOptions) {
            onSelectOptions(options);
        }
    };

    // =============================================================================
    // RENDER FUNCTIONS
    // =============================================================================
    const renderTags = () => (
        <SelectedTagList
            removable={!disabled && !readOnly}
            items={selected.map((item, index) => ({
                key: getTagKey(item, index),
                label: getTagLabel(item),
                onRemove: () =>
                    handleListItemClick(
                        item,
                        valueExtractor ? valueExtractor(item) : item
                    ),
            }))}
        />
    );

    const renderLabel = () => {
        if (!selected || selected.length === 0) {
            return (
                <PlaceholderLabel
                    variant={variant}
                    truncateType={optionTruncationType}
                >
                    {placeholder}
                </PlaceholderLabel>
            );
        } else {
            return (
                <ValueLabel
                    variant={variant}
                    truncateType={optionTruncationType}
                >
                    {getDisplayValue()}
                </ValueLabel>
            );
        }
    };

    const isTagDisplay = displayVariant === "tag";
    const showTags = isTagDisplay && selected.length > 0;

    const renderValue = () => {
        // the tags are not announced, so the combobox has the same value a
        // "count" display would show
        if (showTags) {
            return <VisuallyHidden>{getDisplayValue()}</VisuallyHidden>;
        }

        return (
            <LabelContainer disabled={disabled}>{renderLabel()}</LabelContainer>
        );
    };

    const renderElement = () => {
        return (
            <InputBox
                className={className}
                data-testid={testId}
                id={id}
                ref={nodeRef}
                tabIndex={-1}
                onFocus={handleNodeFocus}
                onBlur={handleNodeBlur}
                focused={focused}
                disabled={disabled}
                readOnly={readOnly}
                error={error}
            >
                <ExpandableElement
                    ref={selectorRef}
                    disabled={disabled}
                    expanded={showOptions}
                    listboxId={internalId}
                    popupRole="listbox"
                    readOnly={readOnly}
                    variant={variant}
                    dynamicHeight={isTagDisplay}
                    // the tags are rendered alongside the combobox since they
                    // contain buttons, and have their own disabled styling
                    content={showTags ? renderTags() : undefined}
                    aria-labelledby={ariaLabelledBy}
                    aria-describedby={ariaDescribedBy}
                    aria-invalid={ariaInvalid}
                >
                    {renderValue()}
                </ExpandableElement>
            </InputBox>
        );
    };

    const renderDropdown = () => {
        return (
            <DropdownList
                listboxId={internalId}
                listItems={options}
                onSelectItem={handleListItemClick}
                onDismiss={handleListDismiss}
                valueExtractor={valueExtractor}
                listExtractor={listExtractor}
                enableSearch={enableSearch}
                searchFunction={searchFunction}
                searchPlaceholder={searchPlaceholder}
                multiSelect
                maxSelectable={maxSelectable}
                selectedItems={selected}
                onSelectAll={handleSelectAllClick}
                onRetry={onRetry}
                itemsLoadState={optionsLoadState}
                itemTruncationType={optionTruncationType}
                renderListItem={renderListItem}
                hideNoResultsDisplay={hideNoResultsDisplay}
                noResultsDescription={noResultsDescription}
                customLabels={customLabels}
                renderCustomCallToAction={renderCustomCallToAction}
                variant={variant}
                width={dropdownWidth}
                matchElementWidth
            />
        );
    };

    return (
        <DropdownListState>
            <ElementWithDropdown
                enabled={!readOnly && !disabled}
                isOpen={showOptions}
                renderElement={renderElement}
                renderDropdown={renderDropdown}
                onOpen={handleOpen}
                onClose={handleClose}
                onDismiss={handleDismiss}
                clickToToggle
                offset={8}
                alignment={alignment}
                fitAvailableHeight
                customZIndex={dropdownZIndex}
                rootNode={dropdownRootNode}
            />
        </DropdownListState>
    );
};
